def format_markdown(answer, contexts):
    for context in contexts:
        # print(context)
        title = context['metadata']['title']
        url = context['metadata']['url']
        # pattern = re.escape(f"[{title}]")
        # pattern = re.compile(rf'\[{re.escape(title)}\]')
        pattern = re.compile(rf'\[{re.escape(title)}[^\]]*?\]')
        replacement = f"[{title}]({url})"
        print(replacement)
        answer = re.sub(pattern, replacement, answer)
    return f"## Robotic Fiber Handling in Datacenters: Summary\n\n{answer.strip()}"

